sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {
    // Link to Employee Center (esc) instead of the platform UI
    var base = gs.getProperty('glide.servlet.uri') + 'esc?id=';
    var url;
    var label;

    if (current.getTableName() == 'sysapproval_approver') {
        if (current.getValue('state') == 'requested') {
            // Approver: open the approval in the portal
            url = base + 'approval&table=sysapproval_approver&sys_id=' + current.getUniqueValue();
            label = 'Open approval in Employee Center';
        } else {
            // Requester: open the approved / rejected request
            url = base + 'ticket&table=' + current.getValue('source_table') + '&sys_id=' + current.getValue('sysapproval');
            label = 'View request in Employee Center';
        }
    } else {
        url = base + 'ticket&table=' + current.getTableName() + '&sys_id=' + current.getUniqueValue();
        label = 'View ' + current.getValue('number') + ' in Employee Center';
    }

    template.print('<a href="' + url + '">' + label + '</a>');
})(current, template, email, email_action, event);
